/*
 * GSM SMS Sender — Board 1
 * Sends an SMS message every 5 seconds using SIM800/SIM900 GSM module
 * via AT commands.
 */

#include <GSM.h>

GSM gsm;

String recipient = "+1234567891";
int msgCount = 0;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  Serial.println("GSM SMS Sender Starting...");

  // Initialize GSM module
  gsm.begin();

  Serial.println("GSM SMS Sender ready!");
  Serial.println("IMEI: " + gsm.getIMEI());
  Serial.println("---");
}

void loop() {
  msgCount++;

  Serial.print("Sending SMS #");
  Serial.println(msgCount);

  String message = "GSM SMS #" + String(msgCount) + " from Sender";
  gsm.sendSMS(recipient, message);

  Serial.println("SMS sent!");
  Serial.println("---");

  delay(5000);
}

