/*
 * GSM SMS Receiver — Board 2
 * Receives SMS messages from Board 1 and displays them on Serial Monitor.
 */

#include <GSM.h>

GSM gsm;

void setup() {
  Serial.begin(115200);
  while (!Serial);

  Serial.println("GSM SMS Receiver Starting...");

  // Initialize GSM module
  gsm.begin();

  Serial.println("GSM SMS Receiver ready — waiting for SMS...");
  Serial.println("---");
}

void loop() {
  // Read any received SMS
  String sms = gsm.readSMS();
  if (sms.length() > 0) {
    Serial.print("Received SMS: ");
    Serial.println(sms);
    Serial.println("---");
  }

  delay(1000);
}
